31: // Transition represents a state machine transition for a machine of type SM with state S and event E.
32: type Transition[S comparable, SM StateMachine[S], E any] struct {
33: 	// Source states that are valid for this transition.
34: 	Sources []S
35: 	// Destination state to transition to.
36: 	Destination S
37: 	// Function to apply the transition. Mutate the state machine object here and return tasks.
38: 	apply func(SM, E) (TransitionOutput, error)
39: }
40: 
41: // NewTransition creates a new [Transition] from the given source states to a destination state for a given event.
42: // The apply function is called after verifying the transition is possible and setting the destination state.
43: func NewTransition[S comparable, SM StateMachine[S], E any](src []S, dst S, apply func(SM, E) (TransitionOutput, error)) Transition[S, SM, E] {
44: 	return Transition[S, SM, E]{
45: 		Sources:     src,
46: 		Destination: dst,
47: 		apply:       apply,
48: 	}
49: }
50: 
51: // Possible returns a boolean indicating whether the transition is possible for the current state.
52: func (t Transition[S, SM, E]) Possible(sm SM) bool {
53: 	return slices.Contains(t.Sources, sm.State())
54: }
55: 
56: // Apply applies a transition event to the given state machine changing the state machine's state to the transition's
57: // Destination on success.
58: func (t Transition[S, SM, E]) Apply(sm SM, event E) (TransitionOutput, error) {
59: 	prevState := sm.State()
60: 	if !t.Possible(sm) {
61: 		return TransitionOutput{}, fmt.Errorf("%w from %v: %v", ErrInvalidTransition, prevState, event)
62: 	}
63: 
64: 	sm.SetState(t.Destination)
65: 	return t.apply(sm, event)
66: }

