411: func (l *Loader) resolveParallel(ctx context.Context, nodes []*FetchTreeNode) error {
412: 	// Plain errgroup.Group (NOT errgroup.WithContext)
413: 	// as parallel fetches runs independently
414: 	var g errgroup.Group
415: 	for i := range nodes {
416: 		node := nodes[i]
417: 		g.Go(func() error {
418: 			// Propagate genuine processing errors (e.g. result merge failures,
419: 			// pre-fetch validation errors) so they surface as a top-level error,
420: 			// matching the serial execution path. Recoverable subgraph fetch
421: 			// errors are recorded into the response during the merge phase and
422: 			// return nil, so they never reach here. A plain errgroup.Group (no
423: 			// context) does not cancel siblings on error, so returning here does
424: 			// not interrupt the rest of the parallel group; they run to completion.
425: 			return l.resolveFetchNodeWithCtx(ctx, node)
426: 		})
427: 	}
428: 	if err := g.Wait(); err != nil {
429: 		return errors.WithStack(err)
430: 	}
431: 	return nil
432: }
